export function concatInt16(frames) {
  const total = frames.reduce((sum, frame) => sum + frame.length, 0);
  const pcm = new Int16Array(total);
  let offset = 0;
  for (const frame of frames) {
    pcm.set(frame, offset);
    offset += frame.length;
  }
  return pcm;
}
export function int16ToBytes(pcm) {
  const bytes = new Uint8Array(pcm.byteLength);
  bytes.set(new Uint8Array(pcm.buffer, pcm.byteOffset, pcm.byteLength));
  return bytes;
}
export function float32ToInt16(samples) {
  const pcm = new Int16Array(samples.length);
  for (let index = 0; index < samples.length; index += 1) {
    const sample = Number(samples[index]);
    const clamped = Math.max(-1, Math.min(1, sample));
    pcm[index] = clamped < 0 ? clamped * 32768 : clamped * 32767;
  }
  return pcm;
}
export function resampleInt16Linear(input, fromRate, toRate) {
  if (fromRate === toRate || input.length === 0) return input.slice();
  const outLength = Math.max(1, Math.round((input.length * toRate) / fromRate));
  const output = new Int16Array(outLength);
  const scale = (input.length - 1) / Math.max(outLength - 1, 1);
  for (let index = 0; index < outLength; index += 1) {
    const position = index * scale;
    const leftIndex = Math.floor(position);
    const rightIndex = Math.min(leftIndex + 1, input.length - 1);
    const fraction = position - leftIndex;
    const left = Number(input[leftIndex]);
    const right = Number(input[rightIndex]);
    output[index] = Math.round(left + (right - left) * fraction);
  }
  return output;
}
